/* Local device check only. Streams are never transmitted or recorded. */
window.AssemblyMedia=(()=>{
 let stream=null,pending=false,epoch=0,ctx=null,raf=null;
 const modal=document.createElement('dialog');modal.className='media-dialog';modal.setAttribute('aria-label','Camera and microphone check');document.body.append(modal);
 modal.innerHTML='<header><h2>Private device preview</h2><button type="button" data-media="close" aria-label="Close device check">Close</button></header><p class="media-note">Test your devices here. To see and hear others, join the live lobby or classroom meeting.</p><video autoplay muted playsinline aria-label="Your camera preview"></video><div class="media-controls"><button type="button" data-media="camera" aria-pressed="false">Camera off</button><button type="button" data-media="mic" aria-pressed="false">Microphone off</button></div><label>Microphone level <meter min="0" max="1" value="0" aria-label="Microphone input level"></meter></label><p role="status" aria-live="polite"></p>';
 const status=t=>modal.querySelector('[role="status"]').textContent=t;
 function labels(){for(const [action,kind] of [['camera','video'],['mic','audio']]){const on=stream?.getTracks().some(t=>t.kind===kind&&t.readyState==='live');const b=modal.querySelector('[data-media="'+action+'"]');b.textContent=(action==='camera'?'Camera':'Microphone')+(on?' on':' off');b.setAttribute('aria-pressed',String(Boolean(on)));}}
 function stop(){epoch++;stream?.getTracks().forEach(t=>t.stop());stream=null;cancelAnimationFrame(raf);ctx?.close();ctx=null;modal.querySelector('video').srcObject=null;modal.querySelector('meter').value=0;labels();}
 function close(){stop();modal.close();}
 async function toggle(kind){if(pending)return;const existing=stream?.getTracks().filter(t=>t.kind===kind)||[];if(existing.length){for(const track of existing){track.stop();stream.removeTrack(track);}if(kind==='audio'){cancelAnimationFrame(raf);ctx?.close();ctx=null;modal.querySelector('meter').value=0;}labels();return;}
 pending=true;const ticket=epoch;status('Waiting for device permission?');try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Device access requires HTTPS and a supported browser.');const acquired=await navigator.mediaDevices.getUserMedia({video:kind==='video',audio:kind==='audio'});if(ticket!==epoch||!modal.open){acquired.getTracks().forEach(t=>t.stop());return;}stream??=new MediaStream();acquired.getTracks().forEach(t=>stream.addTrack(t));modal.querySelector('video').srcObject=stream;if(kind==='audio'){ctx=new AudioContext();await ctx.resume();const analyser=ctx.createAnalyser();analyser.fftSize=256;ctx.createMediaStreamSource(new MediaStream(stream.getAudioTracks())).connect(analyser);const values=new Uint8Array(analyser.fftSize);const level=()=>{if(!ctx)return;analyser.getByteTimeDomainData(values);modal.querySelector('meter').value=Math.min(1,Math.sqrt(values.reduce((sum,v)=>sum+((v-128)/128)**2,0)/values.length)*4);raf=requestAnimationFrame(level);};level();}status('Preview only. Nothing is recorded or shared.');}catch(e){if(ticket===epoch)status(e.name==='NotAllowedError'?'Permission denied. Allow camera or microphone access in your browser settings and try again.':e.name==='NotFoundError'?'No matching device was found. Connect a device and try again.':e.message);}finally{pending=false;labels();}}
 modal.addEventListener('click',e=>{const action=e.target.closest('[data-media]')?.dataset.media;if(action==='close')close();if(action==='camera')toggle('video');if(action==='mic')toggle('audio');});modal.addEventListener('cancel',e=>{e.preventDefault();close();});window.addEventListener('pagehide',stop);
 return {open(){if(window.AssemblyCall?.active()){window.AssemblyCall.show();return;}if(!modal.open)modal.showModal();status('Turn on a device to check it. Closing this panel turns both devices off.');},stop,close};
})();
